"use client";
import { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import { useAuth } from "@/store/auth";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const router = useRouter();
  const { login } = useAuth();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/api/auth/jwt/create/",
        {
          email: email.toLowerCase().trim(), // ← EMAIL LOGIN WORKS NOW
          password: password,
        }
      );

      login(res.data.access, { email });

      const me = await axios.get("http://127.0.0.1:8000/api/auth/users/me/", {
        headers: { Authorization: `Bearer ${res.data.access}` },
      });

      login(res.data.access, me.data);
      alert("Welcome back!");
      router.push("/products");
    } catch (err: any) {
      console.log(err.response?.data);
      alert("Wrong email or password");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-cyan-50">
      <form
        onSubmit={handleLogin}
        className="bg-white p-12 rounded-3xl shadow-2xl w-96"
      >
        <h2 className="text-4xl font-bold text-center mb-10 text-blue-600">
          Login
        </h2>

        <input
          type="email"
          placeholder="Email"
          className="w-full p-4 mb-6 border border-gray-300 rounded-xl text-lg focus:outline-none focus:border-blue-600"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="password"
          placeholder="Passwordaffa"
          className="w-full p-4 mb-8 border border-gray-300 rounded-xl text-lg focus:outline-none focus:border-blue-600"
          required
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button
          type="submit"
          className="w-full bg-blue-600 text-white py-5 rounded-xl text-xl font-bold hover:bg-blue-700 transition"
        >
          Login with Email
        </button>
      </form>
    </div>
  );
}
